using System.Text.Json;
using System.Text.Json.Nodes;
namespace StarlightSyndicateDemo;
public static class GalaxyTests42
{
 public static void Run()
 {
  int checks=0;void Check(bool ok,string message){checks++;if(!ok)throw new Exception("GALAXY FAIL: "+message);}
  var d=Galaxy42.Data;Check(d.Systems.Length==8490&&d.Regions.Length==114&&d.Constellations.Length==1184&&d.Gates.Length==13978,"full record coverage");
  var gates=d.Gates.ToDictionary(g=>g.Id);Check(gates.Count==d.Gates.Length&&Galaxy42.ById.Count==d.Systems.Length,"unique stable keys");
  foreach(var s in d.Systems){Check(Galaxy42.Regions.ContainsKey(s.RegionId)&&Galaxy42.Constellations[s.ConstellationId].ParentId==s.RegionId,"system parent links "+s.Id);Check(s.Position.Length==3&&s.Position.All(double.IsFinite)&&s.Flat.Length==2&&s.Flat.All(double.IsFinite)&&double.IsFinite(s.Security),"finite metre positions "+s.Id);Check(Retheme41.Records["system:"+s.Id].Name==s.Name&&!Retheme41.SourceLorePattern.IsMatch(s.Name),"Starlight identity "+s.Id);foreach(int n in s.Neighbours){Check(Galaxy42.ById[n].Neighbours.Contains(s.Id),"reciprocal system edge");Check(s.Component==Galaxy42.ById[n].Component,"edge component");}foreach(bool three in new[]{false,true})Check(Galaxy42.Project(s,three,.7,.8).IsFinite,"projection "+s.Id);}
  foreach(var g in d.Gates){var other=gates[g.DestinationGateId];Check(other.DestinationGateId==g.Id&&other.SystemId==g.DestinationSystemId&&other.DestinationSystemId==g.SystemId,"reciprocal gate IDs");Check(Galaxy42.ById[g.SystemId].Neighbours.Contains(g.DestinationSystemId),"gate in adjacency");Check(g.Position.Length==3&&g.Position.All(double.IsFinite),"local gate coordinates retained");}
  foreach(var r in d.Regions)Check(r.Members.Order().SequenceEqual(d.Constellations.Where(c=>c.ParentId==r.Id).Select(c=>c.Id).Order()),"region members");foreach(var c in d.Constellations)Check(c.Members.Order().SequenceEqual(d.Systems.Where(s=>s.ConstellationId==c.Id).Select(s=>s.Id).Order()),"constellation members");
  foreach(var p in d.Regions.Concat(d.Constellations)){Check(p.Position.Length==3&&p.Position.All(double.IsFinite)&&p.Flat.Length==2&&p.Flat.All(double.IsFinite),"parent positions");var kind=Galaxy42.Regions.ContainsKey(p.Id)?"region":"constellation";Check(Retheme41.Records[kind+":"+p.Id].Name==p.Name,"parent Starlight identity");}
  Check(d.Components.Sum(c=>c.Systems)==8490&&d.Components.Count(c=>c.Systems==1)==3222&&d.Components.Count(c=>c.Gated)==4,"component report");
  // Independent queue-relaxation oracle, distinct from the production priority-queue search.
  Dictionary<int,double> Oracle(int start,GalaxyRouteMode42 mode,HashSet<int>? blocked=null){var dist=new Dictionary<int,double>{{start,0}};var queue=new Queue<int>();var pending=new HashSet<int>{start};queue.Enqueue(start);while(queue.TryDequeue(out int a)){pending.Remove(a);foreach(int b in Galaxy42.ById[a].Neighbours){if(blocked?.Contains(b)==true)continue;var s=Galaxy42.ById[b];double cost=dist[a]+(mode==GalaxyRouteMode42.Shortest?1:1+(s.Security<.45?50:0)+(s.Security<=0?100:0));if(dist.TryGetValue(b,out var old)&&old<=cost)continue;dist[b]=cost;if(pending.Add(b))queue.Enqueue(b);}}return dist;}
  var routeTimes=new List<double>();
  var nodes=d.Systems.Where(s=>s.Component==0).ToArray();Check(nodes.Length==5228,"main component size");var random=new Random(42);bool longerSafer=false;GalaxyRoute42 sample=new(false,[],0,"");
  for(int i=0;i<36;i++){int from=nodes[random.Next(nodes.Length)].Id,to=nodes[random.Next(nodes.Length)].Id;foreach(var mode in Enum.GetValues<GalaxyRouteMode42>()){var watch=System.Diagnostics.Stopwatch.StartNew();var route=Galaxy42.Route(from,to,mode);routeTimes.Add(watch.Elapsed.TotalMilliseconds);Check(route.Found&&route.Systems[0]==from&&route.Systems[^1]==to,"route endpoints");Check(Oracle(from,mode)[to]==route.Cost,"independent optimal cost");Check(route.Systems.Distinct().Count()==route.Systems.Length,"route no cycle");double sum=0;for(int j=1;j<route.Systems.Length;j++){Check(Galaxy42.ById[route.Systems[j-1]].Neighbours.Contains(route.Systems[j]),"every route hop is a gate");sum+=Galaxy42.StepCost(Galaxy42.ById[route.Systems[j]],mode);}Check(sum==route.Cost,"reported route cost");if(mode==GalaxyRouteMode42.Shortest)sample=route;else{Check(route.Jumps>=sample.Jumps,"safer cannot beat minimum hops");if(route.Jumps>sample.Jumps)longerSafer=true;}}
   if(i==0&&sample.Systems.Length>2){int blocked=sample.Systems[1];var alternative=Galaxy42.Route(from,to,GalaxyRouteMode42.Safer,[blocked]);var oracle=Oracle(from,GalaxyRouteMode42.Safer,[blocked]);Check(alternative.Found==oracle.ContainsKey(to),"avoidance reachability");if(alternative.Found)Check(!alternative.Systems.Contains(blocked)&&alternative.Cost==oracle[to],"avoidance optimality");}}
  Check(longerSafer,"real graph safer mode sometimes takes longer route");Check(Galaxy42.Route(30000001,30000001,GalaxyRouteMode42.Shortest).Jumps==0,"same system zero hops");Check(!Galaxy42.Route(0,30000001,GalaxyRouteMode42.Shortest).Found,"unknown endpoint");Check(!Galaxy42.Route(30000001,30000002,GalaxyRouteMode42.Shortest,[30000001]).Found,"avoided endpoint");var isolated=d.Systems.First(s=>s.Neighbours.Length==0);Check(!Galaxy42.Route(30000001,isolated.Id,GalaxyRouteMode42.Safer).Found,"isolated destination");foreach(var c in d.Components.Where(c=>c.Gated&&c.Id!=0)){Check(!Galaxy42.Route(30000001,c.Seed,GalaxyRouteMode42.Shortest).Found,"separate network");int end=Galaxy42.ById[c.Seed].Neighbours[0];Check(Galaxy42.Route(c.Seed,end,GalaxyRouteMode42.Shortest).Jumps==1,"small network works");}
  var old=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string dir=Path.Combine(Path.GetTempPath(),"StarlightGalaxy42-"+Guid.NewGuid());Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);
  try{var world=new DemoWorld();world.NewGame(1);world.Credits=54321;world.Hangar["ammo"]=77;world.GalaxyPlan=new(){Selected=30000002,From=30000001,To=30000002,Mode=GalaxyRouteMode42.Safer,Avoid=[30000003]};string system=world.SystemId;world.Save();var save=JsonNode.Parse(File.ReadAllText(DemoWorld.SavePath))!;Check(save["WorldDefinitionId"]!.GetValue<string>()==DemoWorld.LegacyWorld42&&save["SaveSchemaVersion"]!.GetValue<int>()==54,"world and schema markers");var loaded=new DemoWorld();Check(loaded.Load()&&loaded.SystemId==system&&loaded.Credits==54321&&loaded.Hangar["ammo"]==77,"pilot assets retained");Check(loaded.GalaxyPlan?.Selected==30000002&&loaded.GalaxyPlan.Mode==GalaxyRouteMode42.Safer&&loaded.GalaxyPlan.Avoid.SequenceEqual(new[]{30000003}),"plan round trip");foreach(string key in new[]{"WorldDefinitionId","SaveSchemaVersion","SourceBuild","GalaxyPlan"})save.AsObject().Remove(key);string legacy=save.ToJsonString();File.WriteAllText(DemoWorld.SavePath,legacy);var migrated=new DemoWorld();Check(migrated.Load()&&migrated.WorldDefinitionId==DemoWorld.LegacyWorld42&&migrated.GalaxyPlan==null&&migrated.Hangar["ammo"]==77&&migrated.SystemId==system,"old saves stay in authored cluster");Check(File.ReadAllText(DemoWorld.SavePath+".pre-pass45.bak")==legacy,"legacy save backup");save["WorldDefinitionId"]="sde-3569502";File.WriteAllText(DemoWorld.SavePath,save.ToJsonString());string before=File.ReadAllText(DemoWorld.SavePath);Check(!migrated.Load()&&migrated.SystemId==system&&File.ReadAllText(DemoWorld.SavePath)==before,"future spatial world rejected without overwriting save");save["WorldDefinitionId"]=DemoWorld.LegacyWorld42;save["GalaxyPlan"]=JsonSerializer.SerializeToNode(new GalaxyPlan42{Selected=-1});File.WriteAllText(DemoWorld.SavePath,save.ToJsonString());Check(migrated.Load()&&migrated.GalaxyPlan==null&&migrated.Credits==54321,"invalid plan discarded without asset loss");}
  finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",old);if(Directory.Exists(dir))Directory.Delete(dir,true);}
  var args=Environment.GetCommandLineArgs();int reportIndex=Array.IndexOf(args,"--galaxy-test-report");if(reportIndex>=0&&reportIndex+1<args.Length){var times=routeTimes.Order().ToArray();File.WriteAllText(args[reportIndex+1],JsonSerializer.Serialize(new{Checks=checks,Pairs=36,Modes=2,Oracle="Independent queue relaxation",RouteMedianMs=times[times.Length/2],RouteP95Ms=times[(int)((times.Length-1)*.95)],RouteMaxMs=times[^1],RouteMeasurement="72 searches on the full main component; includes first route warm-up; independent oracle timing excluded."},new JsonSerializerOptions{WriteIndented=true}));}
  Console.WriteLine($"{checks} Pass 42 galaxy checks passed / {d.Systems.Length} systems / {d.Gates.Length} gates / {d.Components.Length} components.");
 }
}
